## Current behavior
I am extending `MatSnackBar` service:

```typescript
import { LiveAnnouncer } from '@angular/cdk/a11y';
import { BreakpointObserver } from '@angular/cdk/layout';
import { Overlay } from '@angular/cdk/overlay';
import { Inject, Injectable, Injector } from '@angular/core';
import { MatSnackBar, MatSnackBarConfig, MAT_SNACK_BAR_DEFAULT_OPTIONS } from '@angular/material';
import { MessageBarComponent } from './message-bar.component';
import { MessageBarType } from './message-bar.model';

@Injectable({
  providedIn: 'root'
})
export class MessageBar extends MatSnackBar {
  constructor(
    private overlay: Overlay,
    private injector: Injector,
    private breakpointObserver: BreakpointObserver,
    private liveAnnouncer: LiveAnnouncer,
    private snackBar: MatSnackBar,
    @Inject(MAT_SNACK_BAR_DEFAULT_OPTIONS) private config: MatSnackBarConfig
  ) {
    super(overlay, liveAnnouncer, injector, breakpointObserver, snackBar, config);
  }

  private message(text: string, type: MessageBarType) {
    const config = new MatSnackBarConfig();
    config.duration = 3000;
    config.panelClass = type;
    config.data = { type, text };
    this.openFromComponent(MessageBarComponent, config);
  }

  info(text: string) {
    this.message(text, MessageBarType.Info);
  }

  warning(text: string) {
    this.message(text, MessageBarType.Warning);
  }

  error(text: string) {
    this.message(text, MessageBarType.Error);
  }
}
```

I am using lazy loading mechanism for loading all the modules. The problem is when I use `providedIn: 'root'`, I get this error when calling `MessageBar` extended service method inside lazy loaded module:

